int32_t pm_sync_config(pm_config_t * config)
{
    mrpc_pm_sync_config_req_t req;
    mrpc_pm_sync_config_resp_t resp;

    if (sizeof(mrpc_pm_sync_config_req_t) > IPC_MSG_BUFFER_SIZE)
        return LS_FAIL;

    req.hdr.id = MRPC_MSG_ID_PM_SYNC_CONFIG;
    req.config = *config;
    if (mrpc_msg_send(&req, sizeof(mrpc_pm_sync_config_req_t), &resp))
        return LS_FAIL;

    return resp.hdr.status;
}

